<script setup lang="ts">
import {ref}from'vue'
import type {Block} from '../types'
import {safeLink,imageStyles} from '../blocks'
import PublicForm from './PublicForm.vue'
import Icon from './Icon.vue'
const props=withDefaults(defineProps<{blocks:Block[];editable?:boolean;selectedId?:string|null}>(),{editable:false})
const emit=defineEmits<{select:[id:string]}>()
const slide=ref<Record<string,number>>({})
function choose(event:MouseEvent,id:string){if(props.editable){event.stopPropagation();emit('select',id)}}
function step(b:Block,d:number){slide.value[b.id]=((slide.value[b.id]||0)+d+(b.items?.length||1))%(b.items?.length||1)}
function videoUrl(url?:string){if(!url)return '';return /^(https?:\/\/|\/(?!\/))[^\s]+\.(mp4|webm)(\?[^\s]*)?$/i.test(url)?url:''}
</script>
<template><template v-for="block in blocks" :key="block.id"><section v-if="!block.hidden" :class="['public-block','block-'+block.type.toLowerCase().replaceAll(' ','-'),{'selectable-block':editable,'chosen-block':selectedId===block.id}]" :style="{textAlign:(block.align as any)||'start'}" @click="choose($event,block.id)"><template v-if="block.children"><h2 v-if="block.title">{{ block.title }}</h2><div class="block-columns" :style="{'--columns':block.children.length}"><div v-for="(column,i) in block.children" :key="i" class="block-column"><BlockRenderer :blocks="column" :editable="editable" :selected-id="selectedId" @select="emit('select',$event)"/><p v-if="editable&&!column.length" class="column-empty">{{ $t('Column') }} {{ i+1 }} · {{ $t('Select this layout, then add a block') }}</p></div></div></template><template v-else-if="block.type==='Hero'"><div class="public-hero-copy"><span class="eyebrow">WELCOME TO SOMETHING DIFFERENT</span><h1>{{ block.title }}</h1><p>{{ block.text }}</p><a v-if="block.button" :href="safeLink(block.link)" class="public-button" @click="editable&&$event.preventDefault()">{{ block.button }} <Icon name="ArrowUpRight" :size="16"/></a></div><img v-if="block.image" :src="block.image" :alt="block.imageAlt||block.title" :style="imageStyles(block)" loading="lazy"/></template><template v-else-if="block.type==='Image'||block.type==='Image + Text'"><img v-if="block.image" :src="block.image" :alt="block.imageAlt||block.text||block.title" :style="imageStyles(block)" loading="lazy"/><div><h2>{{ block.title }}</h2><p>{{ block.text }}</p></div></template><template v-else-if="block.type==='Video'"><h2>{{ block.title }}</h2><video v-if="videoUrl(block.link)" controls preload="metadata" :poster="block.image" :src="videoUrl(block.link)"></video><div v-else class="video-placeholder"><Icon name="Film" :size="40"/><p>{{ $t('Add a direct MP4 or WEBM video URL.') }}</p></div><p>{{ block.text }}</p></template><template v-else-if="block.type==='Slider' && block.items?.length"><h2>{{ block.title }}</h2><div class="content-slider"><figure v-for="(item,i) in block.items" :key="item.id" v-show="i===(slide[block.id]||0)"><img v-if="item.image" :src="item.image" :alt="item.title"/><figcaption><h3>{{ item.title }}</h3><p>{{ item.text }}</p></figcaption></figure><div class="slider-controls"><button @click.stop="step(block,-1)" :aria-label="$t('Previous')"><Icon name="ArrowLeft"/></button><span>{{ (slide[block.id]||0)+1 }} / {{ block.items.length }}</span><button @click.stop="step(block,1)" :aria-label="$t('Next')"><Icon name="ArrowRight"/></button></div></div></template><template v-else-if="block.items?.length"><h2>{{ block.title }}</h2><p v-if="block.text">{{ block.text }}</p><div v-if="block.type==='FAQ'" class="faq-list"><details v-for="item in block.items" :key="item.id"><summary>{{ item.title }}</summary><p>{{ item.text }}</p></details></div><div v-else :class="['content-items','items-'+block.type.toLowerCase().replaceAll(' ','-')]"><article v-for="item in block.items" :key="item.id"><img v-if="item.image" :src="item.image" :alt="item.title" loading="lazy"/><template v-if="block.type==='Testimonials'"><blockquote>{{ item.text }}</blockquote><h3>{{ item.title }}</h3><small>{{ item.role }}</small></template><template v-else><strong v-if="block.type==='Pricing'" class="price-value">{{ item.price }}</strong><h3>{{ item.title }}</h3><small v-if="item.role">{{ item.role }}</small><p>{{ item.text }}</p><a v-if="item.label" :href="safeLink(item.link)" :class="block.type==='Pricing'?'public-button':'item-link'" @click="editable&&$event.preventDefault()">{{ item.label }} <Icon name="ArrowUpRight" :size="14"/></a></template></article></div></template><template v-else-if="['Contact','Newsletter'].includes(block.type)"><h2>{{ block.title }}</h2><p>{{ block.text }}</p><PublicForm :kind="block.type" :disabled="editable"/></template><template v-else-if="['CTA','Banner'].includes(block.type)"><h2>{{ block.title }}</h2><p>{{ block.text }}</p><a v-if="block.button||['Contact','Newsletter'].includes(block.type)" class="public-button" :href="safeLink(block.link||'mailto:hello@example.com')" @click="editable&&$event.preventDefault()">{{ block.button||'Get in touch' }} <Icon name="ArrowRight" :size="16"/></a></template><template v-else-if="block.type==='FAQ'"><h2>{{ block.title }}</h2><details><summary>{{ block.button||'Tell me more' }}</summary><p>{{ block.text }}</p></details></template><template v-else><h2>{{ block.title }}</h2><p>{{ block.text }}</p><img v-if="block.image" :src="block.image" :alt="block.imageAlt||block.title" :style="imageStyles(block)" loading="lazy"/><a v-if="block.button" :href="safeLink(block.link)" class="public-button" @click="editable&&$event.preventDefault()">{{ block.button }}</a></template></section></template></template>
